SELECT COUNT(DISTINCT a.hadm_id) AS number_of_admissions FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id WHERE p.gender = 'F' AND p.anchor_age = 87 AND p.anchor_year_group BETWEEN 82 AND 92 AND d.icd_code IN ('577.0', 'K85*') AND a.dischtime IS NOT NULL;